"""Structured Root Cause Analysis (RCA) and pipeline observability schemas."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any

from pydantic import BaseModel, Field

from app.schemas.decision import ExecutionStrategy, PolicyDecision, SeverityTier


class RCAReport(BaseModel):
    """Structured output generated by SaSa AI (combines Step 7 HITL & INTRODUCT.md 11.4)."""

    agent_name: str = "SaSa AI"
    provider_name: str = "deepseek"
    model_name: str = "deepseek-v4.1-flash"

    # INTRODUCT.md 11.4 required output fields
    summary: str = Field(description="Concise summary of the incident and likely root cause.")
    evidence: list[str] = Field(
        default_factory=list,
        description="Observed telemetry, metric labels, or log facts supporting the analysis.",
    )
    possible_causes: list[str] = Field(
        default_factory=list,
        description="Ranked list of plausible root causes.",
    )
    recommended_action_id: str | None = Field(
        default=None,
        description="Allowlisted remediation action slug, or None if manual intervention is required.",
    )
    risk_level: SeverityTier = SeverityTier.MEDIUM
    confidence: float = Field(default=0.75, ge=0.0, le=1.0)
    requires_approval: bool = True

    # Step 7 Medium/Critical HITL fields for administrator review
    understanding: str = Field(
        default="",
        description="Detailed explanation of what SaSa AI understands about the issue.",
    )
    proposed_resolution: str = Field(
        default="",
        description="Step-by-step resolution proposal for the operator/administrator.",
    )
    expected_impact: str = Field(
        default="",
        description="Expected service and infrastructure impact of executing the proposed action.",
    )
    intended_tools: list[str] = Field(
        default_factory=list,
        description="Read-only MCP or diagnostic tools used or intended for verification.",
    )


class PipelineTraceMetadata(BaseModel):
    """Step 8 execution pipeline trace metadata for observability and evaluation."""

    correlation_id: str
    fingerprint: str
    input_validated: bool = True
    guardrails_passed: bool = True
    deduplicated: bool = False
    cache_hit: bool = False
    jev_backend: str = "heuristic"
    rag_chunks_retrieved: int = 0
    mcp_tools_executed: list[str] = Field(default_factory=list)
    llm_provider: str = "none"
    llm_model: str = "none"
    latency_ms: float = 0.0
    prompt_tokens: int = 0
    completion_tokens: int = 0
    timestamp: datetime = Field(default_factory=lambda: datetime.now(UTC))


class WebhookProcessingResult(BaseModel):
    """Complete response returned by `POST /api/v1/webhooks/grafana`."""

    incident_fingerprint: str
    server_id: str
    alert_name: str
    strategy: ExecutionStrategy
    deduplicated: bool = False
    cache_hit: bool = False
    policy_decision: PolicyDecision | None = None
    rca_report: RCAReport | None = None
    notification_message: str = ""
    telegram_receipt: dict[str, Any] | None = None
    trace: PipelineTraceMetadata
